          x: originX + (Math.random() - 0.5) * 30,
          y: originY + (Math.random() - 0.5) * 30,
          vx: Math.cos(angle) * speed * (Math.random() * 0.8 + 0.6),
          vy: Math.sin(angle) * speed * (Math.random() * 0.8 + 0.6) - 1.8,
          // 初始微向冲上
