        // 2400ms 镜头下沉与淡出完成
        registerTimeout(() => {
          isVisible.value = false;
          emit('unfold-complete');
        }, 2400);
      });
    };

    // =========================================================================
    // 3. 'ink' 特效：东方水墨物理湍流扩散与 destination-out 镂空
    // =========================================================================
    const playInk = () => {
      inkFadeOut.value = false;
