        // 1400ms 后标题文字渐隐
        registerTimeout(() => {
          inkContentFade.value = true;
        }, 1400);

        // 2200ms 后整体淡出
        registerTimeout(() => {
          inkFadeOut.value = true;
        }, 2200);

        // 2600ms 完成水墨穿透
        registerTimeout(() => {
          isVisible.value = false;
          emit('unfold-complete');
        }, 2600);
      });
    };

    // =========================================================================
    // 4. 统一播放调度与对外 API 暴露
    // =========================================================================
    const play = () => {
