      play();
    });
    onBeforeUnmount(() => {
      clearAllTimers();
    });
    return {
      isVisible,
      currentEffect,
      isUnfastened,
      isUnfolding,
      isUnfolded,
      goldCanvasRef,
      cinematicActive,
      cinematicFadeOut,
      inkCanvasRef,
      inkFadeOut,
      inkContentFade,
      handleSealClick,
      unfasten,
      play
    };
  }
});